mapper.select:
SELECT r.* FROM room r WHERE r.contentId = #{contentId}
AND LOWER(r.name) LIKE CONCAT('%', LOWER(#{name}), '%')
ORDER BY r.name ASC

SELECT r.roomIdx, r.contentId,r.name, r.capacity,r.basePrice, CASE WHEN r.refundable = 1 THEN 1 ELSE 0 END AS refundable, CASE WHEN r.breakfastIncluded = 1 THEN 1 ELSE 0 END AS breakfastIncluded, CASE WHEN r.smoking = 1 THEN 1 ELSE 0 END AS smoking, r.imageUrl, r.roomCount, r.status, CASE WHEN r.status = 0 THEN '숙소 측 요청으로 사용 불가능한 방입니다' WHEN IFNULL(SUM( CASE WHEN rr.status = 1
AND rr.checkin <= #{checkoutDate} AND rr.checkout >= #{checkinDate}
THEN 1 ELSE 0 END ), 0) >= r.roomCount THEN '이미 예약된 방입니다' ELSE '예약 가능한 방입니다' END AS availabilityMessage FROM room r LEFT JOIN roomReservation rr ON r.roomIdx = rr.roomIdx AND r.contentId = rr.contentid WHERE r.contentId = #{contentId} GROUP BY r.roomIdx, r.contentId, r.name, r.capacity, r.basePrice, r.imageUrl, r.roomCount, r.status ORDER BY r.roomIdx
